// OpenCRDTSubscription delegates to the CRDT state service.
func (a *App) OpenCRDTSubscription(documentID, deviceID string) (*crdt.State, *crdt.Subscription, func(), error) {
	return a.crdt.OpenSubscription(documentID, deviceID)
}

// AddCRDTSubscription delegates to the CRDT state service.
func (a *App) AddCRDTSubscription(documentID, deviceID string) (*crdt.Subscription, func()) {
	return a.crdt.AddSubscription(documentID, deviceID)
}

// RegisterPush records one freshly established push connection in the
// process-wide in-memory registry. The returned subscription carries the
// server-allocated id and the one-shot active-cancel signal; the connection
// layer removes it when the connection ends.
func (a *App) RegisterPush(deviceID, documentID string, kind push.Kind, cursor int64) *push.Subscription {
	return a.pushSubs.Register(deviceID, documentID, kind, cursor)
}

// UnregisterPush removes an ended push connection.
func (a *App) UnregisterPush(subscriptionID string) {
	a.pushSubs.Unregister(subscriptionID)
}

// ListPushSubscriptions returns the device's live push connections across
// both channels in establishment order. It is a pure memory view.
func (a *App) ListPushSubscriptions(deviceID string) []push.Info {
	return a.pushSubs.List(deviceID)
}

// CancelPushSubscription actively ends one of the device's live push
// connections. It returns false when the id is unknown, already gone, or owned
// by another device; those cases are one indistinguishable 404 at the edge.
func (a *App) CancelPushSubscription(deviceID, subscriptionID string) bool {
	return a.pushSubs.Cancel(deviceID, subscriptionID)
}

// CloseDocumentPush ends every live push connection subscribed to documentID,
// across both channels and every owning device, after its deletion committed.
// Other documents' connections are untouched.
func (a *App) CloseDocumentPush(documentID string) {
	a.pushSubs.CloseDocument(documentID)
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// snapshotVersionRegisterRequest is the body of the collection POST: the
// calling device, the stable version name to create and the existing snapshot
// cursor it is bound to.
type snapshotVersionRegisterRequest struct {
	DeviceID       string          `json:"deviceId"`
	Name           string          `json:"name"`
	SnapshotCursor json.RawMessage `json:"snapshotCursor"`
}

// snapshotVersionBindRequest is the body of the rename (PUT
// .../snapshots/versions/{name}): the calling device and the existing
// snapshot cursor the name is moved onto. The name itself is in the path.
type snapshotVersionBindRequest struct {
	DeviceID       string          `json:"deviceId"`
	SnapshotCursor json.RawMessage `json:"snapshotCursor"`
}

// snapshotVersionRestoreRequest is the body of the by-name restore: the
// calling device and the change id the restored state is appended under. The
// source snapshot is named by the path rather than carried in the body.
type snapshotVersionRestoreRequest struct {
	DeviceID string `json:"deviceId"`
	ChangeID string `json:"changeId"`
}

// snapshotVersionItem fixes the on-the-wire key order of one list entry to
// name then snapshotCursor.
type snapshotVersionItem struct {
	Name   string `json:"name"`
	Cursor int64  `json:"snapshotCursor"`
}

// snapshotVersionListResponse is the list body with the top-level key order
// fixed to versions then count; Versions is always a non-nil slice so an
// empty view serializes as [].
type snapshotVersionListResponse struct {
	Versions []snapshotVersionItem `json:"versions"`
	Count    int                   `json:"count"`
}

// decodeVersionBindRequest enforces the rename endpoint's JSON shape:
// application/json body with a non-empty deviceId and a positive-integer
// snapshotCursor. Every violation is a 400 JSON error and the caller returns
// without touching the store.
func decodeVersionBindRequest(w http.ResponseWriter, r *http.Request) (deviceID string, cursor int64, ok bool) {
	var req snapshotVersionBindRequest
	if !decodeJSONBody(w, r, &req) {
		return "", 0, false
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return "", 0, false
	}
	// snapshotCursor must be present and a positive integer (no fractions,
	// strings, booleans, null or zero).
	if len(req.SnapshotCursor) == 0 {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return "", 0, false
	}
	c, good := parsePositiveInt(req.SnapshotCursor)
	if !good {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return "", 0, false
	}
	return req.DeviceID, c, true
}

// versionDeviceFromQuery resolves the calling device of a bodyless or
// read-only version endpoint from the deviceId query parameter. A missing or
// empty parameter is judged exactly like an unregistered device: a 404 JSON
// error ahead of any version or snapshot observation.
func versionDeviceFromQuery(w http.ResponseWriter, r *http.Request) (string, bool) {
	deviceID := r.URL.Query().Get("deviceId")
	if deviceID == "" {
		writeError(w, http.StatusNotFound, "device not found")
		return "", false
	}
	return deviceID, true
}

// writeVersionGateError maps the shared gate/existence errors of every version
// endpoint onto their fixed status codes, returning true when err was handled.
// The order mirrors the verdict order: device existence (404), permission
// (403), version and snapshot existence (404), conflict (409); none of the
// failure bodies exposes version content.
func writeVersionGateError(w http.ResponseWriter, err error) bool {
	var conflict *events.ErrVersionConflict
	switch {
	case errors.Is(err, store.ErrDeviceNotFound):
		writeError(w, http.StatusNotFound, "device not found")
	case errors.Is(err, store.ErrPermissionDenied):
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
	case errors.Is(err, events.ErrVersionNotFound):
		writeError(w, http.StatusNotFound, "snapshot version not found")
	case errors.Is(err, events.ErrSnapshotNotFound):
		writeError(w, http.StatusNotFound, "snapshot not found")
	case errors.As(err, &conflict):
		writeError(w, http.StatusConflict, "snapshot version is already bound to another cursor: "+conflict.Name)
	default:
		return false
	}
	return true
}

// handlePutSnapshotVersion registers an existing snapshot under a stable
// version name:
//
//	POST /v1/documents/{documentID}/snapshots/versions
//
// The name is unique within the document and travels in the JSON body.
// Binding the same name to the same cursor again is idempotent and returns the
// identical body; binding that name to another cursor (or a name another
// cursor occupies) is a 409 with zero writes. The fixed verdict order is
// request shape (400), device existence (404), document permission (403), then
// snapshot and version existence (404) and the conflict verdict (409). Success
// is one compact JSON line naming the version and the snapshot cursor.
func handlePutSnapshotVersion(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req snapshotVersionRegisterRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.Name == "" {
		writeError(w, http.StatusBadRequest, "name must be a non-empty string")
		return
	}
	// snapshotCursor must be present and a positive integer (no fractions,
	// strings, booleans, null or zero).
	if len(req.SnapshotCursor) == 0 {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return
	}
	cursor, ok := parsePositiveInt(req.SnapshotCursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return
	}

	result, err := s.PutSnapshotVersion(documentID, req.DeviceID, req.Name, cursor)
	if err != nil {
		if !writeVersionGateError(w, err) {
			writeError(w, http.StatusInternalServerError, "failed to register snapshot version")
		}
		return
	}
	writeJSON(w, http.StatusOK, result)
}

// handleListSnapshotVersions is the read-only collection view:
//
//	GET /v1/documents/{documentID}/snapshots/versions?deviceId=D
//
// It returns every registration in ascending version-name order, each entry
// naming only the name and the snapshot cursor; an unknown document (or one
// without markers) reads as an empty array with count 0 rather than an error.
// The calling device must be registered (404) and still authorized (403); the
// read writes nothing and exposes no snapshot state.
func handleListSnapshotVersions(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	deviceID, ok := versionDeviceFromQuery(w, r)
	if !ok {
		return
	}

	versions, err := s.ListSnapshotVersions(documentID, deviceID)
	if err != nil {
		if !writeVersionGateError(w, err) {
			writeError(w, http.StatusInternalServerError, "failed to list snapshot versions")
		}
		return
	}

	items := make([]snapshotVersionItem, 0, len(versions))
	for _, v := range versions {
		items = append(items, snapshotVersionItem{Name: v.Name, Cursor: v.Cursor})
	}
	writeJSON(w, http.StatusOK, snapshotVersionListResponse{Versions: items, Count: len(items)})
}

// handleGetSnapshotVersion reads the snapshot state a version name points at:
//
//	GET /v1/documents/{documentID}/snapshots/versions/{name}?deviceId=D
//
// The body is byte-for-byte the by-cursor snapshot read
// ({"cursor":N,"state":...}): the state is presented exactly as stored. The
// verdict order is shape (400), device existence (404), permission (403),
// version and snapshot existence (404).
func handleGetSnapshotVersion(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
	name := r.PathValue("name")             // route pattern + guard guarantee non-empty

	deviceID, ok := versionDeviceFromQuery(w, r)
	if !ok {
		return
	}

	cursor, state, err := s.GetSnapshotVersionState(documentID, deviceID, name)
	if err != nil {
		if !writeVersionGateError(w, err) {
			writeError(w, http.StatusInternalServerError, "failed to load snapshot version")
		}
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
}

// handleRebindSnapshotVersion moves an existing version name onto another
// existing snapshot:
//
//	PUT /v1/documents/{documentID}/snapshots/versions/{name}
//
// The verdict order is request shape (400), device existence (404), permission
// (403), then the version marker (a missing name is 404) and the target
// snapshot (a missing cursor, an unknown document included, is 404). Rebinding
// to the cursor already bound is an idempotent no-op with the same body. The
// snapshot itself is never modified.
func handleRebindSnapshotVersion(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
	name := r.PathValue("name")             // route pattern + guard guarantee non-empty

	deviceID, cursor, ok := decodeVersionBindRequest(w, r)
	if !ok {
		return
	}

	result, err := s.RebindSnapshotVersion(documentID, deviceID, name, cursor)
	if err != nil {
		if !writeVersionGateError(w, err) {
			writeError(w, http.StatusInternalServerError, "failed to rename snapshot version")
		}
		return
	}
	writeJSON(w, http.StatusOK, result)
}

// handleDeleteSnapshotVersion hard-deletes one version marker:
//
//	DELETE /v1/documents/{documentID}/snapshots/versions/{name}?deviceId=D
//
// The request carries no body. A missing marker is a 404 JSON error; the
// snapshot itself is untouched and, once the deletion commits, the name is
// free to bind again. Success is one compact JSON line naming the version and
// the deletion marker.
func handleDeleteSnapshotVersion(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
	name := r.PathValue("name")             // route pattern + guard guarantee non-empty

	deviceID, ok := versionDeviceFromQuery(w, r)
	if !ok {
		return
	}

	if err := s.DeleteSnapshotVersion(documentID, deviceID, name); err != nil {
		if !writeVersionGateError(w, err) {
			writeError(w, http.StatusInternalServerError, "failed to delete snapshot version")
		}
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"name": name, "deleted": true})
}

// handleRestoreSnapshotVersion restores the snapshot a version name points at
// as one ordinary change:
//
//	POST /v1/documents/{documentID}/snapshots/versions/{name}/restore
//
// The body names the calling device and the change id; the source snapshot is
// resolved from the path. On a hit the snapshot's state is appended exactly
// like the cursor-based restore in one serialized transaction (the document
// cursor advances by one) and the success body is byte-identical to it.
// Idempotency and conflict follow the existing restore rules: an id occupied
// by an ordinary change is a 409 with zero writes. The verdict order is shape
// (400), device existence (404), permission (403), version and snapshot
// existence (404), then the restore conflict (409).
func handleRestoreSnapshotVersion(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
	name := r.PathValue("name")             // route pattern + guard guarantee non-empty

	var req snapshotVersionRestoreRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.ChangeID == "" {
		writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
		return
	}

	result, err := s.RestoreSnapshotVersion(documentID, req.DeviceID, req.ChangeID, name)
	if err != nil {
		var conflict *events.ErrRestoreConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.Is(err, events.ErrVersionNotFound):
			writeError(w, http.StatusNotFound, "snapshot version not found")
		case errors.Is(err, events.ErrSnapshotNotFound):
			writeError(w, http.StatusNotFound, "snapshot not found")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
		default:
			writeError(w, http.StatusInternalServerError, "failed to restore snapshot version")
		}
		return
	}
	writeJSON(w, http.StatusOK, result)
}

package server

import (
	"errors"
	"net/http"
	"net/url"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// changeExportResponse is the export body with the top-level key order fixed
// to changes then count. Changes is always a non-nil slice so an empty
// export serializes as [] rather than null. Each element is an
// events.ListedChange, whose key order is id, deviceId, payload, cursor — the
// same record the paged read emits.
type changeExportResponse struct {
	Changes []events.ListedChange `json:"changes"`
	Count   int                   `json:"count"`
}

// exportRequested reports whether the query carries the export's from/to
// parameters. A present key counts even with an empty value (?from= is the
// export with the default bound), matching the document-level collection.
func exportRequested(q url.Values) bool {
	if _, ok := q["from"]; ok {
		return true
	}
	_, ok := q["to"]
	return ok
}

// parseExportInterval parses the shared from/to export parameters, writing
// the documented 400 on an illegal value. from defaults to 0; a nil to means
// the interval has no upper bound; to below from is rejected. It is shared by
// the document-scoped and session-scoped exports so their query semantics
// cannot drift apart.
func parseExportInterval(w http.ResponseWriter, q url.Values) (from int64, to *int64, ok bool) {
	from = 0
	if raw := q.Get("from"); raw != "" {
		v, valid := parseCursorPath(raw)
		if !valid {
			writeError(w, http.StatusBadRequest, "from must be a non-negative integer")
			return 0, nil, false
		}
		from = v
	}

	if raw := q.Get("to"); raw != "" {
		v, valid := parseCursorPath(raw)
		if !valid {
			writeError(w, http.StatusBadRequest, "to must be a non-negative integer")
			return 0, nil, false
		}
		to = &v
	}
	if to != nil && *to < from {
		writeError(w, http.StatusBadRequest, "to must not be less than from")
		return 0, nil, false
	}
	return from, to, true
}

// writeChangeExport renders an export result in the shared response shape: a
// single compact JSON line with the changes,count key order, an empty export
// serializing as [] with count 0.
func writeChangeExport(w http.ResponseWriter, rows []events.ListedChange) {
	if rows == nil {
		rows = make([]events.ListedChange, 0)
	}
	writeJSON(w, http.StatusOK, changeExportResponse{Changes: rows, Count: len(rows)})
}

// handleExportChanges is the read-only batch export over a document's change
// collection:
//
//	GET /v1/documents/{documentID}/changes?from=0&to=N
//
// from defaults to 0; to absent means no upper bound. Only changes whose
// cursor is in the closed [from, to] interval and still in the online log are
// returned, in ascending cursor order, at most one entry per cursor. An
// unknown document or a range without any online change — including one that
// lies entirely inside the trimmed region — is a successful 200 with an empty
// list and count 0, not an error. Changes compacted out of the online log
// never appear. The handler writes nothing: it creates no change, moves no
// cursor, records no change and notifies the push channels.
func handleExportChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	from, to, ok := parseExportInterval(w, r.URL.Query())
	if !ok {
		return
	}

	rows, err := s.ExportChanges(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export changes")
		return
	}
	writeChangeExport(w, rows)
}

// handleSessionExportChanges is the session-scoped view of the change-log
// batch export, sharing the session change read's exact collection path:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/changes?from=0&to=N
//
// The interval semantics and the response body are identical to the
// document-level export; around them sit the session view's checks in their
// fixed order — request shape and parameters (400), session existence (404),
// the session device's document permission (403) — so a rejected export
// exposes no change content and writes nothing.
func handleSessionExportChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Malformed interval parameters are a request-shape error (400) checked
	// before the resource lookup (404), matching the paged read's ordering.
	from, to, ok := parseExportInterval(w, r.URL.Query())
	if !ok {
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	rows, err := s.ExportChanges(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export changes")
		return
	}
	writeChangeExport(w, rows)
}

// malformedChangeExportPath reports whether p targets the change-log
// collection's export shape but is not the collection's exact location
// (/v1/documents/{documentID}/changes): a trailing slash (an empty trailing
// segment) or extra path segments past the collection. The paged read and
// this export share that exact collection path; its terminal subresources
// (poll, compact, subscribe under the session family) have their own keyword
// guards, so only a genuinely unrecognized suffix reaches this check.
// ServeMux would answer it with a redirect or a plain-text 404/405; the
// change surface promises a JSON error and never a redirect. Empty segments
// are already rejected by the guard itself. The keyword is matched only past
// the documentID position, so a document literally named "changes" keeps its
// ordinary routes.
func malformedChangeExportPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg != "changes" || i == 0 {
			continue
		}
		// Keyword position reached. The collection is exactly
		// {documentID}/changes; the poll and compact subresources are their own
		// endpoints and keep their own guards; the document-level subscription
		// adds one trailing "subscribe" segment and keeps its own endpoint.
		// Anything else (a trailing slash, an unrecognized extra segment) is a
		// malformed 400.
		if i == 1 {
			collection := len(segs) == 2 && segs[0] != ""
			knownSubresource := len(segs) >= 3 &&
				(segs[2] == "poll" || segs[2] == "compact" || segs[2] == "subscribe")
			return !(collection || knownSubresource)
		}
		return false
	}
	return false
}

// malformedSessionChangesPath reports whether p targets the session-scoped
// change collection's shape but is not the collection's exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/changes): extra path
// segments past the collection. The paged read and the interval export share
// that exact collection path; the subscribe subresource has its own endpoint
// and keyword guard, so only a genuinely unrecognized suffix reaches this
// check. ServeMux would answer it with a plain-text 404; the change surface
// promises a JSON 400 and never a redirect. Empty segments (doubled slashes,
// a trailing slash) are already rejected by the guard itself.
//
// "changes" is treated as the collection keyword only in the fourth segment,
// right after the document identifier; a session or document identifier
// literally named "changes" occupies an identifier position and keeps its
// ordinary routes.
func malformedSessionChangesPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "changes" there is an ordinary identifier, not this
	// collection's keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	if len(segs) < 4 || segs[1] != "documents" || segs[3] != "changes" {
		return false
	}
	// Keyword position reached. The collection is exactly
	// {sessionId}/documents/{documentId}/changes; the subscribe subresource
	// adds one trailing "subscribe" segment and keeps its own guard; the long
	// poll adds one trailing "poll" segment and keeps its own guard; the
	// offline replay adds one trailing "replay" segment and keeps its own
	// guard; the single-change merge adds one trailing "merge" segment and
	// keeps its own guard; the change-log compaction adds one trailing
	// "compact" segment and keeps its own guard. Anything else past the
	// keyword is a malformed 400.
	collection := len(segs) == 4 && segs[0] != "" && segs[2] != ""
	subscribe := len(segs) == 5 && segs[4] == "subscribe"
	poll := len(segs) == 5 && segs[4] == "poll"
	replay := len(segs) == 5 && segs[4] == "replay"
	merge := len(segs) == 5 && segs[4] == "merge"
	compact := len(segs) == 5 && segs[4] == "compact"
	return !(collection || subscribe || poll || replay || merge || compact)
}

// malformedSessionCompactPath reports whether p targets the session-scoped
// change-log compaction endpoint but is not at its exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/changes/compact): a missing
// "documents"/"changes" segment, an extra segment, or a "compact" segment in a
// position short of the registered shape. ServeMux would answer those with a
// plain-text 404 (or a redirect for an empty segment); every failure of this
// endpoint must be a JSON 400 instead. Empty segments are already rejected by
// the guard itself.
//
// "compact" is treated as the endpoint keyword only in its terminal segment
// position (the fifth segment, index 4); a session or document identifier
// literally named "compact" occupies an identifier position (index 0 or 2) and
// is therefore left to the ordinary changes routes like any other id.
func malformedSessionCompactPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "compact" there is the CRDT compaction keyword, not
	// the change-log one.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	for i, seg := range segs {
		if seg != "compact" {
			continue
		}
		// Identifier positions: sessionId (0) and documentId (2). A value of
		// "compact" there is an ordinary identifier, not the endpoint word.
		if i == 0 || i == 2 {
			continue
		}
		// Endpoint keyword position: the fifth segment must be exactly
		// "compact" with the documents/changes scaffolding around it, and no
		// segment may follow. Any other occurrence is a malformed path.
