	if w.Code != http.StatusOK || w.Body.String() != "{\"boundary\":0,\"removed\":0}\n" {
		t.Fatalf("unknown compact = %d %q", w.Code, w.Body.String())
	}
	_, body := doRequest(t, h, http.MethodGet, "/v1/documents/ghost/changes")
