// The version rebind 409 now carries the offending version name in a
// structured conflictId field alongside the error message.
func TestSnapshotVersionRebindConflictCarriesConflictID(t *testing.T) {
	h, _ := newTestHandler(t)
	seedVersionFixture(t, h, "dev-1", "doc")
	registerVersion(t, h, "doc", "dev-1", "v1", 1)

	w, body := postJSON(t, h, "/v1/documents/doc/snapshots/versions/v1", map[string]any{
		"deviceId": "dev-1", "snapshotCursor": 2,
	})
	if w.Code != http.StatusConflict {
		t.Fatalf("rebind = %d %s", w.Code, w.Body.String())
	}
	if body["conflictId"] != "v1" || body["error"] == nil {
		t.Fatalf("409 body = %v, want error and conflictId=v1", body)
	}

	// The same structured field is used by the collection POST's rebind
	// conflict.
	w, body = postJSON(t, h, "/v1/documents/doc/snapshots/versions", map[string]any{
		"deviceId": "dev-1", "name": "v1", "snapshotCursor": 2,
	})
	if w.Code != http.StatusConflict || body["conflictId"] != "v1" {
		t.Fatalf("collection conflict = %d body = %v", w.Code, body)
	}
}

